#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <dlfcn.h>
#include <stdint.h>

#define N (20000*1024)
#define REPS 6

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

typedef unsigned char *(*SHA256_fn)(const unsigned char *, size_t, unsigned char *);

int main(int argc, char **argv) {
    const char *lib = argv[1];
    void *h = dlopen(lib, RTLD_NOW);
    if (!h) { printf("dlopen fail %s: %s\n", lib, dlerror()); return 1; }
    SHA256_fn fn = (SHA256_fn)dlsym(h, "SHA256");
    if (!fn) { printf("no SHA256 in %s\n", lib); return 1; }
    unsigned char *data = malloc(N);
    memset(data, 0x5a, N);
    unsigned char out[32];
    fn(data, N, out);
    double t0 = now();
    for (int i=0;i<REPS;i++) fn(data, N, out);
    double t1 = now();
    printf("%s SHA256: %.4f s  %02x%02x\n", lib, t1-t0, out[0], out[1]);

    // also EVP
    typedef void *(*EVP_MD_CTX_new_fn)(void);
    typedef int (*EVP_DigestInit_ex_fn)(void *, const void *, void *);
    typedef int (*EVP_DigestUpdate_fn)(void *, const void *, size_t);
    typedef int (*EVP_DigestFinal_ex_fn)(void *, unsigned char *, unsigned int *);
    typedef void (*EVP_MD_CTX_free_fn)(void *);
    typedef const void *(*EVP_sha256_fn)(void);
    EVP_MD_CTX_new_fn ctx_new = dlsym(h, "EVP_MD_CTX_new");
    EVP_DigestInit_ex_fn dinit = dlsym(h, "EVP_DigestInit_ex");
    EVP_DigestUpdate_fn dupdate = dlsym(h, "EVP_DigestUpdate");
    EVP_DigestFinal_ex_fn dfinal = dlsym(h, "EVP_DigestFinal_ex");
    EVP_MD_CTX_free_fn ctx_free = dlsym(h, "EVP_MD_CTX_free");
    EVP_sha256_fn sha = dlsym(h, "EVP_sha256");
    if (ctx_new && sha) {
        t0 = now();
        for (int i=0;i<REPS;i++) {
            void *ctx = ctx_new();
            dinit(ctx, sha(), NULL);
            dupdate(ctx, data, N);
            unsigned int len=32;
            dfinal(ctx, out, &len);
            ctx_free(ctx);
        }
        t1 = now();
        printf("%s EVP: %.4f s\n", lib, t1-t0);
    }
    return 0;
}
EOF
