#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <nettle/sha2.h>
#include <gcrypt.h>

#define N (20000*1024)
#define REPS 6

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    unsigned char *data = malloc(N);
    memset(data, 0x5a, N);
    unsigned char out[32];

    // nettle
    struct sha256_ctx ctx;
    sha256_init(&ctx);
    sha256_update(&ctx, N, data);
    sha256_digest(&ctx, 32, out);
    double t0 = now();
    for (int i=0;i<REPS;i++) {
        sha256_init(&ctx);
        sha256_update(&ctx, N, data);
        sha256_digest(&ctx, 32, out);
    }
    double t1 = now();
    printf("nettle sha256: %.4f s %02x%02x\n", t1-t0, out[0], out[1]);

    // gcrypt
    if (!gcry_check_version(NULL)) { printf("gcrypt init fail\n"); return 1; }
    gcry_md_hd_t hd;
    gcry_md_open(&hd, GCRY_MD_SHA256, 0);
    gcry_md_write(hd, data, N);
    memcpy(out, gcry_md_read(hd, GCRY_MD_SHA256), 32);
    gcry_md_close(hd);

    t0 = now();
    for (int i=0;i<REPS;i++) {
        gcry_md_open(&hd, GCRY_MD_SHA256, 0);
        gcry_md_write(hd, data, N);
        gcry_md_read(hd, GCRY_MD_SHA256);
        gcry_md_close(hd);
    }
    t1 = now();
    printf("gcrypt sha256: %.4f s\n", t1-t0);

    // gcrypt reuse handle
    gcry_md_open(&hd, GCRY_MD_SHA256, 0);
    t0 = now();
    for (int i=0;i<REPS;i++) {
        gcry_md_reset(hd);
        gcry_md_write(hd, data, N);
        gcry_md_read(hd, GCRY_MD_SHA256);
    }
    t1 = now();
    printf("gcrypt reuse: %.4f s\n", t1-t0);
    gcry_md_close(hd);
    return 0;
}
