import time, os
from Cryptodome.Hash import SHA256
import hashlib
from cryptography.hazmat.primitives import hashes

data = os.urandom(20_000*1024)

def crypto():
    d = hashes.Hash(hashes.SHA256())
    d.update(data)
    return d.finalize()

def pyc():
    return SHA256.new(data).digest()

def hlib():
    return hashlib.sha256(data).digest()

crypto(); pyc(); hlib()
def bench(fn, n=8):
    t0=time.perf_counter()
    for _ in range(n):
        fn()
    return time.perf_counter()-t0
print("crypt", bench(crypto))
print("pycryptodome", bench(pyc))
print("hashlib", bench(hlib))
print("match", crypto()==pyc()==hlib())

# also Cryptodome update path
def pyc2():
    h = SHA256.new()
    h.update(data)
    return h.digest()
pyc2()
print("pyc2", bench(pyc2))
EOF"}

