        for (unsigned i=0;i<lanes*8;i++) mids[i] = 0x6a09e667 + i;
        unsigned char *out = malloc(lanes * 32);
        cl_mem dbuf = clCreateBuffer(ctx, CL_MEM_READ_ONLY, (size_t)lanes*suffix, NULL, &err);
        cl_mem mbuf = clCreateBuffer(ctx, CL_MEM_READ_ONLY, lanes*8*4, NULL, &err);
        cl_mem obuf = clCreateBuffer(ctx, CL_MEM_WRITE_ONLY, lanes*32, NULL, &err);
        cl_uint b = blocks;
        cl_ulong total = (cl_ulong)N; // dummy
        clSetKernelArg(k, 0, sizeof(dbuf), &dbuf);
        clSetKernelArg(k, 1, sizeof(mbuf), &mbuf);
        clSetKernelArg(k, 2, sizeof(b), &b);
        clSetKernelArg(k, 3, sizeof(total), &total);
        clSetKernelArg(k, 4, sizeof(obuf), &obuf);
        size_t g = lanes;
        clEnqueueWriteBuffer(q, dbuf, CL_FALSE, 0, (size_t)lanes*suffix > N ? N : (size_t)lanes*suffix, data, 0, NULL, NULL);
        clEnqueueWriteBuffer(q, mbuf, CL_FALSE, 0, lanes*8*4, mids, 0, NULL, NULL);
        clEnqueueNDRangeKernel(q, k, 1, NULL, &g, NULL, 0, NULL, NULL);
        clFinish(q);
        int reps=3;
        double t0=now();
        for (int i=0;i<reps;i++) {
            clEnqueueWriteBuffer(q, dbuf, CL_FALSE, 0, (size_t)lanes*suffix, data, 0, NULL, NULL);
            clEnqueueWriteBuffer(q, mbuf, CL_FALSE, 0, lanes*8*4, mids, 0, NULL, NULL);
            clEnqueueNDRangeKernel(q, k, 1, NULL, &g, NULL, 0, NULL, NULL);
            clEnqueueReadBuffer(q, obuf, CL_FALSE, 0, lanes*32, out, 0, NULL, NULL);
            clFinish(q);
        }
        double dt=(now()-t0)/reps;
        printf("suffix %6u bytes  lanes %6u  time %.4f s  per-lane %.3f us  suffix-MB/s %.0f\n",
               suffix, lanes, dt, dt/lanes*1e6, (lanes*(double)suffix/1e6)/dt);
        free(mids); free(out);
        clReleaseMemObject(dbuf); clReleaseMemObject(mbuf); clReleaseMemObject(obuf);
    }
    unsigned char ref[32];
    double t0=now();
    for(int i=0;i<3;i++) SHA256(data, N, ref);
    printf("openssl full 20MB: %.4f s\n", (now()-t0)/3);
    return 0;
}
