#include <stdio.h>
#include <stdint.h>
#include <time.h>
#include <string.h>
#include <stdlib.h>
#include <openssl/sha.h>

static inline uint64_t rdtsc() {
    unsigned lo, hi;
    __asm__ volatile("rdtsc" : "=a"(lo), "=d"(hi));
    return ((uint64_t)hi<<32)|lo;
}

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    /* calibrate rdtsc */
    uint64_t c0 = rdtsc();
    double t0 = now();
    while (now()-t0 < 0.2) {}
    uint64_t c1 = rdtsc();
    double t1 = now();
    double hz = (c1-c0)/(t1-t0);
    printf("rdtsc Hz during idle-ish: %.0f MHz\n", hz/1e6);

    size_t N = 20000*1024;
    unsigned char *data = malloc(N);
    memset(data, 0x5a, N);
    unsigned char out[32];
    /* warm */
    SHA256(data, N, out);
    c0 = rdtsc(); t0 = now();
    for (int i=0;i<4;i++) SHA256(data, N, out);
    c1 = rdtsc(); t1 = now();
    printf("during sha256: rdtsc %.0f MHz  wall %.4f s  throughput %.1f MB/s\n",
           (c1-c0)/(t1-t0)/1e6, t1-t0, (4.0*N/1e6)/(t1-t0));
    printf("cycles per byte: %.2f\n", (double)(c1-c0)/(4.0*N));
    return 0;
}
