0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};

/* 4-way interleaved SHA-256 of 4 independent messages, each of length N (multiple of 64, no padding here — compression only). */
static void sha256x4_blocks(uint32_t st[4][8], const uint8_t *m0, const uint8_t *m1, const uint8_t *m2, const uint8_t *m3, size_t nblocks) {
    __m256i a = _mm256_setr_epi32(st[0][0], st[1][0], st[2][0], st[3][0], 0,0,0,0);
    /* We'll keep state in 8 ymm but only low 128 used? Better use __m128i x4 via 256-bit with 4 lanes of 32... 
       4 lanes fit in one __m128i. Use SSE. */
}

/* SSE 4-lane */
static inline __m128i rotr(__m128i x, int n) {
    return _mm_or_si128(_mm_srli_epi32(x, n), _mm_slli_epi32(x, 32-n));
}
static inline __m128i load_be4(const uint8_t *p0, const uint8_t *p1, const uint8_t *p2, const uint8_t *p3) {
    uint32_t w0,w1,w2,w3;
    memcpy(&w0, p0, 4); memcpy(&w1, p1, 4); memcpy(&w2, p2, 4); memcpy(&w3, p3, 4);
    w0 = __builtin_bswap32(w0); w1=__builtin_bswap32(w1); w2=__builtin_bswap32(w2); w3=__builtin_bswap32(w3);
    return _mm_setr_epi32(w0,w1,w2,w3);
}

static void sha256x4(const uint8_t *m0, const uint8_t *m1, const uint8_t *m2, const uint8_t *m3, size_t nblocks, uint32_t out[4][8]) {
    __m128i a = _mm_set1_epi32(0x6a09e667);
    __m128i b = _mm_set1_epi32(0xbb67ae85);
    __m128i c = _mm_set1_epi32(0x3c6ef372);
    __m128i d = _mm_set1_epi32(0xa54ff53a);
    __m128i e = _mm_set1_epi32(0x510e527f);
    __m128i f = _mm_set1_epi32(0x9b05688c);
    __m128i g = _mm_set1_epi32(0x1f83d9ab);
    __m128i h = _mm_set1_epi32(0x5be0cd19);
    for (size_t blk=0; blk<nblocks; blk++) {
        const uint8_t *p0 = m0+blk*64, *p1=m1+blk*64, *p2=m2+blk*64, *p3=m3+blk*64;
        __m128i w[64];
        for (int i=0;i<16;i++) w[i] = load_be4(p0+4*i, p1+4*i, p2+4*i, p3+4*i);
        for (int i=16;i<64;i++) {
            __m128i s0 = _mm_xor_si128(rotr(w[i-15],7), _mm_xor_si128(rotr(w[i-15],18), _mm_srli_epi32(w[i-15],3)));
            __m128i s1 = _mm_xor_si128(rotr(w[i-2],17), _mm_xor_si128(rotr(w[i-2],19), _mm_srli_epi32(w[i-2],10)));
            w[i] = _mm_add_epi32(_mm_add_epi32(w[i-16], s0), _mm_add_epi32(w[i-7], s1));
        }
        __m128i A=a,B=b,C=c,D=d,E=e,F=f,G=g,H=h;
        for (int i=0;i<64;i++) {
            __m128i S1 = _mm_xor_si128(rotr(E,6), _mm_xor_si128(rotr(E,11), rotr(E,25)));
            __m128i ch = _mm_xor_si128(_mm_and_si128(E,F), _mm_andnot_si128(E,G));
            __m128i t1 = _mm_add_epi32(H, _mm_add_epi32(S1, _mm_add_epi32(ch, _mm_add_epi32(_mm_set1_epi32(K[i]), w[i]))));
            __m128i S0 = _mm_xor_si128(rotr(A,2), _mm_xor_si128(rotr(A,13), rotr(A,22)));
            __m128i maj = _mm_xor_si128(_mm_and_si128(A,B), _mm_xor_si128(_mm_and_si128(A,C), _mm_and_si128(B,C)));
            __m128i t2 = _mm_add_epi32(S0, maj);
            H=G; G=F; F=E; E=_mm_add_epi32(D,t1); D=C; C=B; B=A; A=_mm_add_epi32(t1,t2);
        }
        a=_mm_add_epi32(a,A); b=_mm_add_epi32(b,B); c=_mm_add_epi32(c,C); d=_mm_add_epi32(d,D);
        e=_mm_add_epi32(e,E); f=_mm_add_epi32(f,F); g=_mm_add_epi32(g,G); h=_mm_add_epi32(h,H);
    }
    __m128i regs[8] = {a,b,c,d,e,f,g,h};
    for (int i=0;i<8;i++) {
        uint32_t tmp[4];
        _mm_storeu_si128((__m128i*)tmp, regs[i]);
        out[0][i]=tmp[0]; out[1][i]=tmp[1]; out[2][i]=tmp[2]; out[3][i]=tmp[3];
    }
}

