       Compare midstate via a known implementation: hash 64 zero-pad manually is hard.
       Just check 4 lanes identical. */
    int same = 1;
    for (int i=0;i<8;i++) if (out[0][i]!=out[1][i]||out[0][i]!=out[2][i]) same=0;
    printf("lanes identical %d state0=%08x\n", same, out[0][0]);

    size_t nblocks = (N/4)/64; /* each lane gets N/4 bytes */
    size_t lane = nblocks*64;
    uint8_t *data = malloc(lane*4);
    memset(data, 0x5a, lane*4);
