    for (int i=0;i<REPS;i++) sha256x4(data, data+lane, data+2*lane, data+3*lane, nblocks, out);
    double t1=now();
    printf("sha256x4 of %zu bytes total: %.4f s (%.1f MB/s)\n", lane*4, t1-t0, REPS*(lane*4/1e6)/(t1-t0));

    unsigned char ref[32];
    t0=now();
    for(int i=0;i<REPS;i++) SHA256(data, lane*4, ref);
    t1=now();
    printf("openssl same bytes: %.4f s (%.1f MB/s)\n", t1-t0, REPS*(lane*4/1e6)/(t1-t0));
